&Options = new() &OptionsDesc = new() &OptionIndexes = new() LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_ADMLOGCHA' Do 'LoadAdmLogChaOptions' Case &DDOName.ToUpper() = !'DDO_ADMLOGOBJ' Do 'LoadAdmLogObjOptions' Case &DDOName.ToUpper() = !'DDO_ADMLOGUSU' Do 'LoadAdmLogUsuOptions' Case &DDOName.ToUpper() = !'DDO_ADMLOGIP' Do 'LoadAdmLogIPOptions' Case &DDOName.ToUpper() = !'DDO_ADMLOGDAD' Do 'LoadAdmLogDadOptions' EndCase
&OptionsJson = &Options.ToJson() &OptionsDescJson = &OptionsDesc.ToJson() &OptionIndexesJson = &OptionIndexes.ToJson()
