Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"Auditoria.AliEscLogWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"Auditoria.AliEscLogWWGridState")) Else &GridState.FromXml(&Session.Get(!"Auditoria.AliEscLogWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFADMLOGCHA" &TFAdmLogCha.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGCHA_SEL" &TFAdmLogCha_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGOBJ" &TFAdmLogObj.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGOBJ_SEL" &TFAdmLogObj_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGUSU" &TFAdmLogUsu.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGUSU_SEL" &TFAdmLogUsu_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGTIP_SEL" &TFAdmLogTip_SelsJson = &GridStateFilterValue.Value &TFAdmLogTip_Sels.FromJson(&TFAdmLogTip_SelsJson) Case &GridStateFilterValue.Name = !"TFADMLOGDTHR" &TFAdmLogDtHr.FromString(&GridStateFilterValue.Value) &TFAdmLogDtHr_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFADMLOGIP" &TFAdmLogIP.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGIP_SEL" &TFAdmLogIP_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGDAD" &TFAdmLogDad.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFADMLOGDAD_SEL" &TFAdmLogDad_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'ADMLOGIP' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AdmLogIP1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'ADMLOGTIP' &AdmLogTip1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'ADMLOGUSU' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AdmLogUsu1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'ADMLOGDTHR' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AdmLogDtHr1.FromString(&GridStateDynamicFilter.Value) &AdmLogDtHr_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'ADMLOGCHA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AdmLogCha1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'ADMLOGIP' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AdmLogIP2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'ADMLOGTIP' &AdmLogTip2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'ADMLOGUSU' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AdmLogUsu2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'ADMLOGDTHR' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AdmLogDtHr2.FromString(&GridStateDynamicFilter.Value) &AdmLogDtHr_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'ADMLOGCHA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AdmLogCha2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'ADMLOGIP' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AdmLogIP3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'ADMLOGTIP' &AdmLogTip3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'ADMLOGUSU' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AdmLogUsu3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'ADMLOGDTHR' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AdmLogDtHr3.FromString(&GridStateDynamicFilter.Value) &AdmLogDtHr_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'ADMLOGCHA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AdmLogCha3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadAdmLogChaOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFAdmLogCha = &SearchTxt &TFAdmLogCha_Sel.SetEmpty() For Each AliEscLog Order AdmLogCha using AliEscLogWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &AdmLogIP1, &AdmLogTip1, &AdmLogUsu1, &AdmLogDtHr1 , &AdmLogDtHr_To1, &AdmLogCha1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &AdmLogIP2 , &AdmLogTip2, &AdmLogUsu2, &AdmLogDtHr2, &AdmLogDtHr_To2, &AdmLogCha2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &AdmLogIP3, &AdmLogTip3, &AdmLogUsu3, &AdmLogDtHr3 , &AdmLogDtHr_To3, &AdmLogCha3, &TFAdmLogCha, &TFAdmLogCha_Sel, &TFAdmLogObj, &TFAdmLogObj_Sel , &TFAdmLogUsu, &TFAdmLogUsu_Sel, &TFAdmLogTip_Sels, &TFAdmLogDtHr, &TFAdmLogDtHr_To, &TFAdmLogIP , &TFAdmLogIP_Sel, &TFAdmLogDad, &TFAdmLogDad_Sel) Where prefCodigo = &prefCodigo
&count = 0 For Each AliEscLog Order AdmLogCha &count += 1 EndFor If not AdmLogCha.IsEmpty() &Option = AdmLogCha
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
